@js:
if (result.indexOf("下一章") > -1) {
mat = baseUrl.match(/\/\d+(_(\d+))?\.html/);
page = Number(mat[2]||1)+1;
baseUrl.replace(/\/(\d+)(_(\d+))?.html/,'/$1_'+page+'.html');
}

